278	    while (spalte >= 1 && spalte <= reihe.positionen.length) {
279	      const position = reihe.positionen.find((p) => p.spalte === spalte);
280	      if (position?.typ === 'Sitzplatz') {
281	        this.setzeFokus({ reihe: aktuell.reihe, spalte });
